// Last updated: 8/3/2026, 12:45:54 PM
import java.util.ArrayList;
import java.util.List;

class Solution {
    public List<Integer> maxActiveSectionsAfterTrade(String s, int[][] queries) {
            int n = s.length();
                    int[] type = new int[n];
                            int[] start = new int[n];
                                    int[] end = new int[n];
                                            int[] len = new int[n];
                                                    int[] blockId = new int[n];
                                                            int numBlocks = 0;
                                                                    
                                                                            for (int i = 0; i < n; ) {
                                                                                        int j = i;
                                                                                                    while (j < n && s.charAt(j) == s.charAt(i)) {
                                                                                                                    blockId[j] = numBlocks;
                                                                                                                                    j++;
                                                                                                                                                }
                                                                                                                                                            type[numBlocks] = s.charAt(i) - '0';
                                                                                                                                                                        start[numBlocks] = i;
                                                                                                                                                                                    end[numBlocks] = j - 1;
                                                                                                                                                                                                len[numBlocks] = j - i;
                                                                                                                                                                                                            numBlocks++;
                                                                                                                                                                                                                        i = j;
                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                        
                                                                                                                                                                                                                                                int[] prefZeroBlocks = new int[numBlocks + 1];
                                                                                                                                                                                                                                                        for (int i = 0; i < numBlocks; i++) {
                                                                                                                                                                                                                                                                    prefZeroBlocks[i + 1] = prefZeroBlocks[i] + (type[i] == 0 ? 1 : 0);
                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                                                                            int[] pref1 = new int[n + 1];
                                                                                                                                                                                                                                                                                                    for (int i = 0; i < n; i++) {
                                                                                                                                                                                                                                                                                                                pref1[i + 1] = pref1[i] + (s.charAt(i) == '1' ? 1 : 0);
                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                        int maxK = (int) (Math.log(numBlocks) / Math.log(2)) + 1;
                                                                                                                                                                                                                                                                                                                                                if (maxK < 1) {
                                                                                                                                                                                                                                                                                                                                                            maxK = 1;
                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                                                    int[][] stZMax = new int[maxK][numBlocks];
                                                                                                                                                                                                                                                                                                                                                                                            int[][] stOMin = new int[maxK][numBlocks];
                                                                                                                                                                                                                                                                                                                                                                                                    int[][] stZSumMax = new int[maxK][numBlocks];
                                                                                                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                                                                                    for (int i = 0; i < numBlocks; i++) {
                                                                                                                                                                                                                                                                                                                                                                                                                                stZMax[0][i] = type[i] == 0 ? len[i] : -1;
                                                                                                                                                                                                                                                                                                                                                                                                                                            stOMin[0][i] = type[i] == 1 ? len[i] : Integer.MAX_VALUE;
                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (type[i] == 1) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        int left = i > 0 ? len[i - 1] : 0;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        int right = i < numBlocks - 1 ? len[i + 1] : 0;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        stZSumMax[0][i] = left + right;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    } else {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    stZSumMax[0][i] = -1;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        for (int k = 1; k < maxK; k++) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    for (int i = 0; i + (1 << k) <= numBlocks; i++) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    stZMax[k][i] = Math.max(stZMax[k - 1][i], stZMax[k - 1][i + (1 << (k - 1))]);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    stOMin[k][i] = Math.min(stOMin[k - 1][i], stOMin[k - 1][i + (1 << (k - 1))]);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    stZSumMax[k][i] = Math.max(stZSumMax[k - 1][i], stZSumMax[k - 1][i + (1 << (k - 1))]);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        int[] log = new int[numBlocks + 1];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                for (int i = 2; i <= numBlocks; i++) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            log[i] = log[i / 2] + 1;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    List<Integer> ans = new ArrayList<>();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    for (int q = 0; q < queries.length; q++) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                int L = queries[q][0];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            int R = queries[q][1];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        int gL = blockId[L];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    int gR = blockId[R];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // Fix: The problem asks for the maximum active sections in the ENTIRE string, 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // so our baseline needs to be all the '1's in 's' (pref1[n]).
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    int total1sInString = pref1[n];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            int zeroCount = prefZeroBlocks[gR + 1] - prefZeroBlocks[gL];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (zeroCount < 2) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ans.add(total1sInString);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        continue;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            int mZ = -1;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (type[gL] == 0) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        mZ = Math.max(mZ, end[gL] - L + 1);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (type[gR] == 0) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                mZ = Math.max(mZ, R - start[gR] + 1);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (gL + 1 <= gR - 1) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    int k = log[(gR - 1) - (gL + 1) + 1];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    mZ = Math.max(mZ, Math.max(stZMax[k][gL + 1], stZMax[k][gR - 1 - (1 << k) + 1]));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        int y = Integer.MAX_VALUE;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (gL + 1 <= gR - 1) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    int k = log[(gR - 1) - (gL + 1) + 1];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    y = Math.min(y, Math.min(stOMin[k][gL + 1], stOMin[k][gR - 1 - (1 << k) + 1]));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        int x = -1;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                int k1 = gL + 1;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (k1 < gR && type[k1] == 1) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            int leftZ = (k1 - 1 == gL) ? (end[gL] - L + 1) : len[k1 - 1];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            int rightZ = (k1 + 1 == gR) ? (R - start[gR] + 1) : len[k1 + 1];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            x = Math.max(x, leftZ + rightZ);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                int k2 = gR - 1;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (k2 > gL && type[k2] == 1) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            int leftZ = (k2 - 1 == gL) ? (end[gL] - L + 1) : len[k2 - 1];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            int rightZ = (k2 + 1 == gR) ? (R - start[gR] + 1) : len[k2 + 1];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            x = Math.max(x, leftZ + rightZ);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (gL + 2 <= gR - 2) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                int k = log[(gR - 2) - (gL + 2) + 1];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                x = Math.max(x, Math.max(stZSumMax[k][gL + 2], stZSumMax[k][gR - 2 - (1 << k) + 1]));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ans.add(total1sInString + Math.max(x, mZ - y));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return ans;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }